CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,name TEXT UNIQUE NOT NULL,pass TEXT NOT NULL,salt TEXT NOT NULL,role TEXT DEFAULT 'user',banned INTEGER DEFAULT 0,bio TEXT DEFAULT '',created TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,uid INTEGER NOT NULL,exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS threads(id INTEGER PRIMARY KEY AUTOINCREMENT,cid INTEGER NOT NULL,uid INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,pinned INTEGER DEFAULT 0,locked INTEGER DEFAULT 0,deleted INTEGER DEFAULT 0,created TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT,tid INTEGER NOT NULL,uid INTEGER NOT NULL,body TEXT NOT NULL,deleted INTEGER DEFAULT 0,created TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS likes(uid INTEGER,kind TEXT,tid INTEGER,PRIMARY KEY(uid,kind,tid));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,from_id INTEGER NOT NULL,to_id INTEGER NOT NULL,body TEXT NOT NULL,read INTEGER DEFAULT 0,created TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER NOT NULL,kind TEXT NOT NULL,target INTEGER NOT NULL,reason TEXT NOT NULL,status TEXT DEFAULT 'open',created TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS i_posts ON posts(tid);
CREATE INDEX IF NOT EXISTS i_msg ON messages(from_id,to_id);
INSERT INTO categories(name) SELECT 'ทั่วไป' WHERE NOT EXISTS(SELECT 1 FROM categories);
INSERT INTO categories(name) SELECT 'ถามตอบ' WHERE (SELECT COUNT(*) FROM categories)=1;
INSERT INTO categories(name) SELECT 'ประกาศ' WHERE (SELECT COUNT(*) FROM categories)=2;
